    names = sorted(packages, reverse=(name_order == "descending"))
    best_key = None
    best = None

    def visit(chosen, bounds, edges):
        nonlocal best_key, best
        # Reject any newly accumulated constraint that conflicts with a choice.
        for name, version in chosen.items():
            low, high = bounds[name]
            if not low <= version <= high:
                return

        pending = [name for name in bounds if name not in chosen]
        if not pending:
            finished, active = set(), set()

            def acyclic(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not acyclic(other) for other in edges.get(name, ())):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(acyclic(name) for name in chosen):
                return
            key = tuple(chosen.get(name, -1) for name in names)
            if best_key is None or (key > best_key if preference == "maximum" else key < best_key):
                best_key, best = key, dict(chosen)
            return

        # The package order is fixed for reproducibility; all choices are searched.
        name = min(pending)
        low, high = bounds[name]
        versions = [row for row in packages[name]
                    if low <= row["version"] <= high
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        versions.sort(key=lambda row: row["version"], reverse=(preference == "maximum"))
        for row in versions:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_bounds = dict(bounds)
            next_edges = {key: list(value) for key, value in edges.items()}
            active_deps = [dep for dep in row.get("deps", [])
                           if not dep.get("feature") or dep.get("feature") in features]
            next_edges[name] = [dep["name"] for dep in active_deps]
            valid = True
            for dep in active_deps:
                other = dep["name"]
                dep_low, dep_high = dep["min"], dep["max"]
                if other in next_bounds:
                    old_low, old_high = next_bounds[other]
                    dep_low, dep_high = max(old_low, dep_low), min(old_high, dep_high)
                if dep_low > dep_high:
                    valid = False
                    break
                next_bounds[other] = (dep_low, dep_high)
            if valid:
                visit(next_chosen, next_bounds, next_edges)

    roots = {name: (bounds[0], bounds[1]) for name, bounds in data["roots"].items()}
    visit({}, roots, {})
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


